    requires n >= 0
    ensures result == fib4_value(n)
{
    // Initialize the first four values of the sequence
    var a := 0; // fib4(0)
    var b := 0; // fib4(1)
    var c := 2; // fib4(2)
    var d := 0; // fib4(3)

    // Handle base cases
    if n == 0 {
        return a;
    } else if n == 1 {
        return b;
    } else if n == 2 {
        return c;
    } else if n == 3 {
        return d;
    }

    // Compute fib4 for n >= 4 iteratively
    var result := 0;
    var i := 4;

    while i <= n {
        result := a + b + c + d; // fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)

        // Shift the values for the next iteration
        a := b;
        b := c;
        c := d;
        d := result;

        i := i + 1;
    }

    return result;
}

